INSERT INTO `productos` (`item_id`, `name`, `brand`, `rate`, `stock_on_hand`, `sku`, `status`, `cf_marca`, `cf_t_entrega`, `cf_garant_a`, `created_time`, `last_modified_time`, `imagenes_url`, `config_options`, `datasheet_url`, `categoria`, `user_manual`, `description`, `especificaciones`, `tablas`) VALUES
('', 'Motores de Alta Tensión a Prueba de Explosión para Variador de Frecuencia Serie YBBP355-560', 'WOLONG', 0, 10, 'YBBP355-560', 'active', 'WOLONG', 'Bajo consulta', '12 meses contra defectos de fabricación', '2026-07-11 12:55:05', '2026-07-11 12:55:05', '[\"https://ingprosuppliers.com/wp-content/uploads/2024/11/motor1.png\",\"https://ingprosuppliers.com/wp-content/uploads/2024/11/motor2.png\",\"https://ingprosuppliers.com/wp-content/uploads/2024/11/motor3.png\"]', '{}', 'https://ingprosuppliers.com/wp-content/uploads/2024/08/YBBP_Series_Motor_-_SEAMO_MOTOR_Technical_Manual.pdf', 'Motores de Alta Tensión', 'https://ingprosuppliers.com/wp-content/uploads/2024/08/YBBP_Series_Motor_-_SEAMO_MOTOR_Technical_Manual.pdf', '{\r\n        \"titulo\":\"Descripción\",\r\n        \"secciones\":[\r\n            {\r\n                \"tipo\":\"parrafo\",\r\n                \"contenido\":\"La serie YBBP355-560 de Wolong corresponde a motores trifásicos asíncronos de alta tensión a prueba de explosión, diseñados específicamente para operar con variadores de frecuencia (VFD) en ambientes industriales con atmósferas potencialmente explosivas. Su construcción robusta y certificación Ex db permiten su utilización en industrias como petróleo y gas, petroquímica, minería, energía, química y otras aplicaciones de proceso continuo.\"\r\n            },\r\n            {\r\n                \"tipo\":\"parrafo\",\r\n                \"contenido\":\"La familia cubre un rango de potencia desde 160 kW hasta 2240 kW, tensiones nominales de 6 kV y 10 kV, configuraciones desde 2 hasta 12 polos y protección IP55 estándar, con opciones IP56, IP65 e IP66. Está disponible con enfriamiento IC416 o IC411 y diferentes configuraciones de montaje según los requerimientos del proyecto.\"\r\n            },\r\n            {\r\n                \"tipo\":\"parrafo\",\r\n                \"contenido\":\"Estos motores son adecuados para bombas, compresores, ventiladores, sopladores, molinos, trituradoras, cintas transportadoras y otras aplicaciones de alto desempeño que requieren control mediante variadores de velocidad, alta eficiencia energética y operación confiable en ambientes severos.\"\r\n            },\r\n            {\r\n                \"tipo\":\"parrafo\",\r\n                \"contenido\":\"Como opciones de fábrica pueden incorporarse calefactores anticondensación, sensores RTD para rodamientos y devanados, monitoreo de vibraciones, diferentes grados de protección, pinturas especiales para ambientes corrosivos y configuraciones personalizadas de tensión, frecuencia y montaje.\"\r\n            }\r\n        ]\r\n    }', '{\n  \"Potencia\": \"160–2240 kW\",\n  \"Voltaje\": \"6000V / 10000V\",\n  \"Frecuencia\": \"5–50 Hz\",\n  \"Polos\": \"2P–12P\",\n  \"Protección\": \"IP55\",\n  \"Protección Opcional\": \"IP56 / IP65 / IP66\",\n  \"Enfriamiento\": \"IC416\",\n  \"Montaje\": \"IMB3\",\n  \"Clase Térmica\": \"155(F)\",\n  \"Temperatura Ambiente\": \"-20°C a +40°C\",\n  \"Marcado Ex\": \"Ex db I Mb / Ex db IIB T4 Gb / Ex db IIC T4 Gb\",\n  \"Color\": \"RAL5012 Light Blue\",\n  \"Eficiencia\": \"GB30254 Level 2\"\n}', '{\n  \"tablas\": [\n    {\n      \"titulo\": \"Table 2 — Standard and optional configuration\",\n      \"columnas\": [\"Item\",\"Standard\",\"Option\",\"Inquiry\"],\n      \"filas\": [\n        [\"Frame size\",\"H355～560\",\"—\",\"Non-standard frame size\"],\n        [\"Range of power\",\"160kW～2240kW\",\"—\",\"Non-standard power\"],\n        [\"Pole number\",\"2P～12P\",\"—\",\"—\"],\n        [\"Voltage\",\"6000V, 10000V\",\"—\",\"3kV～11kV\"],\n        [\"Frequency\",\"5–50Hz\",\"5–60Hz, 30–50Hz\",\"—\"],\n        [\"Mounting method\",\"IMB3\",\"IMB35, IMV1\",\"IMV1 with axial force\"],\n        [\"Protection degree\",\"IP55\",\"IP56\",\"IP65, IP66\"],\n        [\"Explosion-proof class\",\"Ex db I Mb; Ex db IIB T4 Gb; Ex db IIC T4 Gb\",\"—\",\"dbIIBT5; dbIICT5\"],\n        [\"Cooling method\",\"IC416\",\"IC411\",\"—\"],\n        [\"Thermal class / Temperature rise\",\"155(F), 80K\",\"180(H)\",\"—\"],\n        [\"Operation type\",\"S1\",\"—\",\"Other type\"],\n        [\"Vibration velocity\",\"2.3 mm/s\",\"1.8 mm/s\",\"1.5 mm/s\"],\n        [\"Noise\",\"JB/T 12881-2016; 110 dB(A)\",\"≤95 dB(A)\",\"—\"],\n        [\"Efficiency\",\"Level 2 GB30254\",\"Level 1\",\"GB30254-2024 compliant\"],\n        [\"Painting color\",\"RAL5012 Light Blue\",\"Custom\",\"—\"],\n        [\"Ambient temperature\",\"-20～40°C\",\"-40～60°C\",\"Other\"],\n        [\"Altitude\",\"≤1000m\",\"≤2000m\",\">2000m\"]\n      ]\n    },\n    {\n      \"titulo\":\"Table 3 — Executive standards\",\n      \"columnas\":[\"Standard name\",\"National standard\",\"International standard\"],\n      \"filas\":[\n        [\"Rotary motor quota and performance\",\"GB/T 755\",\"IEC 60034-1\"],\n        [\"Construction / installation / terminal box location\",\"GB/T 997\",\"IEC 60034-7\"],\n        [\"Test methods for three-phase asynchronous motors\",\"GB/T 1032\",\"IEC 60034-2-1\"],\n        [\"Cooling method\",\"GB/T 1993\",\"IEC 60034-6\"],\n        [\"IP code classification\",\"GB/T 4942.1\",\"IEC 60034-5\"],\n        [\"Explosive environments — general requirements\",\"GB/T 3836.1\",\"IEC 60079-0\"],\n        [\"Flameproof enclosure d\",\"GB/T 3836.2\",\"IEC 60079-1\"],\n        [\"Energy efficiency grade\",\"GB 30254-2024\",\"—\"],\n        [\"YBBP HV flameproof VFD motors requirements\",\"JB/T 12881-2016\",\"—\"]\n      ]\n    },\n    {\n      \"titulo\":\"Table 4 — Bearings configuration\",\n      \"columnas\":[\"Frame-pole\",\"Standard\",\"Optional\"],\n      \"filas\":[\n        [\"500-2\",\"Sleeve bearing with forced lubrication\",\"Sleeve bearing self-lubricating / Rolling bearing\"],\n        [\"560-2\",\"Sleeve bearing with forced lubrication\",\"—\"],\n        [\"Others\",\"Rolling bearing\",\"—\"]\n      ]\n    },\n    {\n      \"titulo\":\"Table 5 — Oil consumption\",\n      \"columnas\":[\"Frame-pole\",\"Oil volume\",\"Oil type\",\"Oil pressure range